#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;
    const long long mod = 998244353;
    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    vector<vector<long long>> dp(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= min(i, n); j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
            }
            dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % mod) % mod;
        }
    }
    long long total = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            total = (total + dp[i][j] * dp[2 * n - i][j] % mod * fact[j] % mod) % mod;
        }
    }
    auto powFast = [&](long long base, long long exp) {
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    };
    long long inv1 = powFast(dp[2 * n][0], mod - 2);
    long long inv2 = powFast(2 * n + 1, mod - 2);
    cout << (l * total % mod * inv1 % mod * inv2 % mod) << "\n";
    return 0;
}
